var screamVoiceNames=window.screamVoiceNames=window.screamVoiceNames||["尖叫 1", "尖叫 2", "尖叫 3", "尖叫 4", "尖叫 5", "尖叫 6", "尖叫 7", "尖叫 8", "尖叫 9", "裂瓷尖啸", "镜片医生嘶叫", "湿发病患喉音", "逆笑断续尖叫", "暗影低吼"];
// Shared, gesture-unlocked audio context; no new context or network request per scare.
var screamWaveData=window.screamWaveData=window.screamWaveData||["", "", "", "", "", "", "", "", "", "", "", "", "", ""];
var screamContext=window.screamContext||null,screamBuffers=window.screamBuffers||[],screamLoading=window.screamLoading||null,activeScream=window.activeScream||null,lastScreamVariant=window.lastScreamVariant||-1;
function warmScreamAudio(){const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return Promise.resolve(false);if(!screamContext)screamContext=new Context();if(screamContext.state==='suspended')screamContext.resume().catch(()=>{});if(screamBuffers.length)return Promise.resolve(true);if(screamLoading)return screamLoading;screamLoading=Promise.all(screamWaveData.map(base64=>{const raw=atob(base64),bytes=new Uint8Array(raw.length);for(let n=0;n<raw.length;n++)bytes[n]=raw.charCodeAt(n);return screamContext.decodeAudioData(bytes.buffer)})).then(buffers=>{screamBuffers=buffers;return true}).catch(()=>{screamLoading=null;return false});return screamLoading}
function chooseScreamVariant(count,previous,random=Math.random){if(count<2)return 0;if(previous<0)return Math.floor(random()*count);return (previous+1+Math.floor(random()*(count-1)))%count}
function playJumpScream(forcedVariant=null){if(typeof jumpScaresEnabled!=='undefined'&&!jumpScaresEnabled)return Promise.resolve(false);if(typeof difficulty!=='undefined'&&difficulty==='peaceful')return Promise.resolve(false);return warmScreamAudio().then(ready=>{if(!ready||(typeof freeCamera!=='undefined'&&freeCamera.enabled)||(typeof jumpScaresEnabled!=='undefined'&&!jumpScaresEnabled)||difficulty==='peaceful'||screamContext.state!=='running')return false;stopPursuitVoice();if(activeScream){try{activeScream.stop()}catch(_){}}const index=Number.isInteger(forcedVariant)&&forcedVariant>=0&&forcedVariant<screamBuffers.length?forcedVariant:chooseScreamVariant(Math.min(9,screamBuffers.length),lastScreamVariant>=9?-1:lastScreamVariant);lastScreamVariant=index;const source=screamContext.createBufferSource(),gain=screamContext.createGain(),limiter=screamContext.createDynamicsCompressor();source.buffer=screamBuffers[index];limiter.threshold.value=-14;limiter.knee.value=12;limiter.ratio.value=8;limiter.attack.value=.003;limiter.release.value=.10;const t=screamContext.currentTime+.01,duration=source.buffer.duration;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.58,t+.005);gain.gain.setValueAtTime(.58,t+Math.max(.02,duration-.10));gain.gain.linearRampToValueAtTime(0,t+duration);source.connect(gain);gain.connect(limiter);limiter.connect(screamContext.destination);activeScream=source;source.onended=()=>{source.disconnect();gain.disconnect();limiter.disconnect();if(activeScream===source)activeScream=null};source.start(t);return true})}
for(const type of ['pointerdown','keydown','touchstart'])window.addEventListener(type,()=>warmScreamAudio(),{capture:true,once:true,passive:true});

var activePursuitVoice=window.activePursuitVoice||null;
function playPursuitVoice(index,distance){if((typeof freeCamera!=='undefined'&&freeCamera.enabled)||difficulty==='peaceful'||paused)return Promise.resolve(false);return warmScreamAudio().then(ready=>{if(!ready||(typeof freeCamera!=='undefined'&&freeCamera.enabled)||difficulty==='peaceful'||paused||screamContext.state!=='running')return false;if(activePursuitVoice){try{activePursuitVoice.stop()}catch(_){}}const source=screamContext.createBufferSource(),gain=screamContext.createGain();const voice=index>=7?portraitGhostDefinitions[index-7]?.voice:(9+index)%screamBuffers.length;source.buffer=screamBuffers[voice??0];source.playbackRate.value=.72+(index%7)*.055;const volume=Math.max(.025,.22*(1-Math.min(distance,25)/28));gain.gain.value=volume;source.connect(gain);gain.connect(screamContext.destination);activePursuitVoice=source;source.onended=()=>{source.disconnect();gain.disconnect();if(activePursuitVoice===source)activePursuitVoice=null};source.start(screamContext.currentTime+.01);return true})}
function stopPursuitVoice(){if(activePursuitVoice){try{activePursuitVoice.stop()}catch(_){}activePursuitVoice=null}}

function stopJumpScream(){if(activeScream){try{activeScream.stop()}catch(_){}activeScream=null}}
